const pages=[...document.querySelectorAll('.page')];
function showPage(id){pages.forEach(p=>p.classList.toggle('active-page',p.id===id));document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===id));window.scrollTo({top:0,behavior:'smooth'});}
document.querySelectorAll('.nav').forEach(n=>n.addEventListener('click',()=>{showPage(n.dataset.page);document.querySelector('.sidebar').classList.remove('open')}));
document.getElementById('menu').addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2200)}
function reviewArchitecture(){toast('Architecture review complete · Overall score 81% · 4 findings');}
function setCmd(c){document.getElementById('command').value=c;document.getElementById('command').focus()}
function runCommand(){const input=document.getElementById('command');const out=document.getElementById('terminalOut');const c=input.value.trim();if(!c)return;let r='';if(c.includes('kubectl get pods'))r='payment-api-7f8c9d  2/2  Running\npayment-worker-5cc2  1/1  Running\npostgres-exporter    1/1  Running';else if(c.includes('logs'))r='ERROR: connection pool exhausted\nFATAL: remaining connection slots are reserved\nretrying connection in 500ms';else if(c.includes('database'))r='PostgreSQL active connections: 492 / 500\nIdle in transaction: 137\nPool waiters: 86';else if(c.includes('deployment'))r='Deployment payment-api changed 9 minutes ago\nImage: payment-api:2026.10.08.4\nRollout: successful';else r='Command accepted. Collect additional evidence before mitigation.';out.textContent='$ '+c+'\n\n'+r;input.value=''}
const search=document.getElementById('globalSearch');search.addEventListener('keydown',e=>{if(e.key==='Enter'&&search.value.trim()){toast('Searching knowledge base for: '+search.value.trim());search.blur()}});
